        const normalizedGlobalRepoAuditCommand =
    normalizeCasualGateText(comando);

const isExactGlobalRepoAuditCommand =
    /^(?:jarvis[\s,]+|heberto[\s,]+|gestia[\s,]+)?(?:analiza|analizar|audita|auditar|revisa|revisar)\s+(?:el\s+)?(?:repo|repositorio)$/.test(
        normalizedGlobalRepoAuditCommand
    );

if (isExactGlobalRepoAuditCommand) {
    console.info(
        "[TERMINAL_GLOBAL_REPO_AUDIT_41_44]",
        { command: comando, traceId: currentTraceId, writeAllowed: false }
    );

    let auditResult = null;

    if (window.ToolsBridge?.executeAndCompose) {
        auditResult = await window.ToolsBridge.executeAndCompose(
            "repo.audit",
            {},
            {
                rawInput: comando,
                analysisId: currentTraceId,
                traceId: currentTraceId,
                source: "terminal_global_repo_audit_41_44",
                tenantId:
                    window.session?.tenantId ||
                    window.KernelHeberto?.session?.tenantId ||
                    "UXMAL39",
                approved: false,
                codexApproved: false
            }
        );
    }
    else if (window.JarvisToolRuntime?.execute) {
        auditResult = await window.JarvisToolRuntime.execute(
            "repo.audit",
            {},
            {
                rawInput: comando,
                analysisId: currentTraceId,
                traceId: currentTraceId,
                source: "terminal_global_repo_audit_41_44",
                approved: false,
                codexApproved: false
            }
        );
    }

    if (typeof window.rehydrateRepoCognitionIndex === "function") {
        window.rehydrateRepoCognitionIndex();
    }

    const auditCandidates = [
        auditResult,
        auditResult?.data,
        auditResult?.data?.data,
        auditResult?.response,
        auditResult?.response?.data,
        auditResult?.result,
        auditResult?.result?.data,
        auditResult?.result?.observations?.[0]?.response?.data
    ].filter(Boolean);

    const auditPayload =
        auditCandidates.find(item =>
            Array.isArray(item?.files) ||
            Array.isArray(item?.modules) ||
            Number.isFinite(item?.totalFiles) ||
            Number.isFinite(item?.count)
        ) || {};

    const rawFiles =
        Array.isArray(auditPayload.files)
            ? auditPayload.files
            : Array.isArray(window.__FULL_REPO_STRUCTURE__)
                ? window.__FULL_REPO_STRUCTURE__
                : Object.keys(window.__REPO_INDEX__ || {});

    const files = rawFiles
        .map(item =>
            typeof item === "string"
                ? item
                : item?.path || item?.file || item?.name || ""
        )
        .filter(Boolean);

    const cognition = Object.entries(window.__REPO_COGNITION__ || {});
    const graph = window.__REPO_DEP_GRAPH__ || {};
    const health = window.__RUNTIME_HEALTH_MAP__ || {};

    const modules = new Set([
        ...Object.keys(window.__MODULE_OWNERSHIP__ || {}),
        ...cognition.map(([, node]) => node?.module).filter(Boolean),
        ...(Array.isArray(auditPayload.modules)
            ? auditPayload.modules.map(item =>
                typeof item === "string"
                    ? item
                    : item?.name || item?.module || item?.id || ""
            )
            : [])
    ].filter(Boolean));

    const critical = cognition.filter(([, node]) =>
        node?.critical === true ||
        node?.cognition?.governance === "CRITICAL" ||
        Number(node?.cognition?.criticality || 0) >= 90
    );

    const highRisk = cognition.filter(([, node]) =>
        node?.cognition?.riskLevel === "HIGH" ||
        Number(node?.cognition?.criticality || 0) >= 70
    );

    const missingGraph = cognition
        .filter(([file]) => !graph[file])
        .map(([file]) => file);

    const criticalWithoutDependencies = critical
        .filter(([file]) => Number(graph?.[file]?.totalDependencies || 0) === 0)
        .map(([file]) => file);

    const unhealthy = Object.entries(health).filter(([, node]) =>
        (node?.state && node.state !== "ONLINE") ||
        Number(node?.health ?? 100) < 90
    );

    const domains = {
        jarvis: files.filter(file => /jarvis|gestia-core|brain|semantic|intent/i.test(file)),
        flotilla: files.filter(file => /flota|flotilla|vehicul|gps|visor-flota/i.test(file)),
        b2b: files.filter(file => /b2b|cmms|mantenimiento/i.test(file)),
        cliente: files.filter(file => /cliente/i.test(file)),
        tecnico: files.filter(file => /tecnico/i.test(file)),
        admin: files.filter(file => /admin|ceo/i.test(file)),
        firebase: files.filter(file => /firebase|firestore|storage|functions/i.test(file))
    };

    const functionCount = Number(
        auditPayload.totalFunctions ||
        auditPayload.functionsCount ||
        auditPayload.functionCount ||
        0
    );

    const findings = [];

    if (missingGraph.length) {
        findings.push(`- Grafo incompleto: ${missingGraph.length} nodos cognitivos no tienen nodo de dependencia.`);
    }

    if (criticalWithoutDependencies.length) {
        findings.push(`- Falsa lectura de impacto: ${criticalWithoutDependencies.length} archivos críticos aparecen con 0 dependencias.`);
    }

    if (unhealthy.length) {
        findings.push(`- Runtime degradado: ${unhealthy.length} módulos no están ONLINE o tienen salud menor a 90.`);
    }

    const flotillaWithoutGraph = domains.flotilla.filter(file => !graph[file]);

    if (domains.flotilla.length === 0) {
        findings.push("- Flotilla no está claramente registrada en el índice global; revisar clasificación del dominio.");
    }
    else if (flotillaWithoutGraph.length) {
        findings.push(`- Flotilla: ${flotillaWithoutGraph.length} de ${domains.flotilla.length} archivos no están conectados al grafo.`);
    }

    if (!findings.length) {
        findings.push("- Sin inconsistencias estructurales obvias en los índices actuales; falta auditoría semántica por flujo de negocio.");
    }

    const topCritical = critical.slice(0, 10).map(([file, node]) =>
        `- ${file} | módulo ${node?.module || "ND"} | criticidad ${node?.cognition?.criticality ?? "ND"}`
    );

    const report = [
        "ANÁLISIS GLOBAL DEL REPOSITORIO SIA7",
        "",
        "Inventario real disponible:",
        `- Archivos detectados: ${Number(auditPayload.totalFiles || auditPayload.count || files.length || cognition.length)}`,
        `- Módulos detectados: ${modules.size}`,
        `- Funciones detectadas: ${functionCount || "ND; el índice actual no entrega conteo global confiable"}`,
        `- Nodos cognitivos: ${cognition.length}`,
        `- Nodos del grafo: ${Object.keys(graph).length}`,
        `- Archivos críticos: ${critical.length}`,
        `- Archivos de riesgo alto: ${highRisk.length}`,
        "",
        "Cobertura por dominio:",
        `- Cerebro/Jarvis: ${domains.jarvis.length} archivos`,
        `- Flotilla: ${domains.flotilla.length} archivos`,
        `- B2B/CMMS: ${domains.b2b.length} archivos`,
        `- Cliente: ${domains.cliente.length} archivos`,
        `- Técnico: ${domains.tecnico.length} archivos`,
        `- Admin/CEO: ${domains.admin.length} archivos`,
        `- Firebase/Functions: ${domains.firebase.length} archivos`,
        "",
        "Hallazgos:",
        ...findings,
        "",
        "Nodos críticos prioritarios:",
        ...(topCritical.length ? topCritical : ["- ND"]),
        "",
        "Siguiente prioridad:",
        "1. Completar dependencias reales antes de confiar en riesgo LOW o impacto 0.",
        "2. Auditar cerebro/Jarvis, flotilla y B2B por flujo completo, no por coincidencias de texto.",
        "3. Mantener lectura únicamente; no se generó patch ni escritura."
    ].join("\n");

    window.renderJarvisResponse?.(
        "Análisis global SIA7",
        report,
        findings.some(item => /incompleto|falsa|degradado|no están conectados|no está claramente/i.test(item))
            ? "warning"
            : "success"
    );

    handled = true;
    return;
}

